schemas.schema-01-systematic.prisma:
/// Master list of discussion board categories. Governs allowable top-level
/// topics for posts. Referenced by posts and visible to all user roles.
/// Category codes and names must be unique and changes are rare, supporting
/// stable system-wide topic organization.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique category code used by internal systems and APIs. Immutable for
  /// reference integrity.
  code String

  /// Display name for the category (e.g., 'Politics', 'Economics'). Used in UI
  /// and filters.
  name String

  /// Detailed category description for moderators and admins. Aids in content
  /// and category management.
  description String?

  /// Relative sort order for displaying categories. Lower values appear first.
  sort_order Int @db.Integer

  /// Timestamp when category was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when category was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if active, set when logically deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  political_economic_board_posts political_economic_board_posts[]

  @@unique([code])
  @@unique([name])
  @@index([sort_order])
}

/// Approved tag vocabulary for labeling posts. Tags improve search,
/// filtering, and content organization. Managed by admins to ensure
/// consistency and prevent spam. Tag names must be unique, and tags may be
/// disabled rather than deleted to maintain history integrity.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique tag text used for post labeling, discovery, and search.
  name String

  /// Human-oriented explanation of what content this tag should label. Shown
  /// in tag selectors, hover, admin panels.
  description String?

  /// Whether this tag can be assigned to new posts. Used to disable tags
  /// without deleting historical references.
  enabled Boolean

  /// Order for admin/UIs to present tags. Lower values show first.
  sort_order Int @db.Integer

  /// Timestamp when tag was added.
  created_at DateTime @db.Timestamptz

  /// Timestamp when tag details were last modified.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if active, else set when logically deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([name])
  @@index([enabled])
  @@index([sort_order])
}

/// Centralized storage for system-wide configuration. Stores arbitrary
/// business key/value/description records adjusted by admins at runtime.
/// Each key must be unique and contains an optional description, supporting
/// runtime audit and configuration versioning. Used for all persistent
/// system parameters not requiring dedicated tables.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique configuration option key. Used for programmatic lookups and
  /// application behavior toggles.
  key String

  /// Raw configuration value or JSON block, depending on setting. Contains
  /// current setting used by applications and services.
  value String

  /// Human-readable explanation of option, for admin panels and audit logs.
  description String?

  /// Timestamp option was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp option was last changed.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null means active. Config marked deleted is never
  /// used at runtime.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
}

/// Immutable log of significant system, admin, and configuration changes.
/// Each record documents a user action, system event, or data mutation
/// requiring permanent traceability for compliance, regulatory, or security
/// purposes. Audit logs support platform transparency, trust, and legal
/// review.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Business category of audit event (e.g., 'role_change', 'settings_update',
  /// 'user_action'). Enables filtering and reporting on log categories.
  event_type String

  /// Who performed the action/event. May reference any user/admin. For data
  /// minimization, this field may be kept even if user deleted.
  actor_id String @db.Uuid

  /// Type of object affected by the event (e.g., 'member', 'post',
  /// 'settings'). Enables multi-entity audits.
  target_type String

  /// ID of the affected object/entity (may reference various tables depending
  /// on event_type). Required for cross-entity auditing.
  target_id String @db.Uuid

  /// Detailed, human-friendly summary of event, for transparency and legal
  /// review.
  description String

  /// Arbitrary extra data, typically in JSON string if relevant. Enables
  /// extensibility of audit record without schema change.
  metadata String?

  /// Timestamp log was created (immutable after insert).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_type])
  @@index([actor_id])
  @@index([target_type])
  @@index([created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Represents guest users visiting politicalEconomicBoard. Used to track
/// anonymous access, metadata (such as browser, device, IP), temporary
/// tokens for guest sessions, and rate-limiting behavior. Guests may
/// transition to registered members upon sign-up. No business actions are
/// permitted for this role. Relationships: None direct. Serves as a
/// reference for anonymous activity and system operation statistics.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique browser/session token to track guest anonymously.
  session_token String

  /// Last known IP address of the guest user.
  ip_address String?

  /// User agent string (browser/device) of the guest.
  user_agent String?

  /// Timestamp for guest session creation.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last guest session update.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for guest session, if terminated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([session_token])
  @@index([created_at])
}

/// Stores all registered members with verified accounts on the platform.
/// Contains identity and basic contact/authentication info, verification and
/// registration metadata (excluding profile, which is in separate table).
/// Members can be upgraded to moderators or administrators (with reference
/// to role change logs).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Email address for login/verification (must be unique).
  email String

  /// Password hash for authentication purposes.
  hashed_password String

  /// Whether the email address is verified.
  is_email_verified Boolean

  /// Timestamp of most recent member login.
  last_login_at DateTime? @db.Timestamptz

  /// IP address during member registration.
  registration_ip String?

  /// Timestamp the member joined the platform.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last member data update.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp if member deletes/leaves platform.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  political_economic_board_moderators political_economic_board_moderators?
  political_economic_board_administrators political_economic_board_administrators?
  political_economic_board_auth_sessions political_economic_board_auth_sessions[]
  political_economic_board_verification_tokens political_economic_board_verification_tokens[]
  political_economic_board_password_resets political_economic_board_password_resets[]
  political_economic_board_role_changes political_economic_board_role_changes[]
  political_economic_board_profiles political_economic_board_profiles?
  political_economic_board_profile_changes political_economic_board_profile_changes[]
  political_economic_board_posts political_economic_board_posts[]
  political_economic_board_post_histories political_economic_board_post_histories[]
  political_economic_board_post_statuses political_economic_board_post_statuses[]
  political_economic_board_comments political_economic_board_comments[]
  political_economic_board_comment_histories political_economic_board_comment_histories[]
  political_economic_board_post_votes political_economic_board_post_votes[]
  political_economic_board_comment_votes political_economic_board_comment_votes[]
  political_economic_board_post_reactions political_economic_board_post_reactions[]
  political_economic_board_comment_reactions political_economic_board_comment_reactions[]
  political_economic_board_reports political_economic_board_reports[]
  political_economic_board_appeals political_economic_board_appeals[]
  political_economic_board_notifications political_economic_board_notifications[]
  political_economic_board_notification_prefs political_economic_board_notification_prefs[]
  political_economic_board_event_logs political_economic_board_event_logs[]
  political_economic_board_metrics political_economic_board_metrics[]
  political_economic_board_data_anomalies political_economic_board_data_anomalies[]

  @@unique([email])
  @@index([created_at])
  @@index([last_login_at])
}

/// Elevated user accounts with moderation privileges. Linked to members
/// (one-to-one, as only members may be promoted). Maintains
/// activation/deactivation timestamps, moderator notes, and event status.
/// Permanent audit trail required for promotion/demotion actions (see
/// political_economic_board_role_changes).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged member's {@link political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// Timestamp moderator privileges were granted.
  activated_at DateTime @db.Timestamptz

  /// Timestamp moderator role revoked or expired, if applicable.
  deactivated_at DateTime? @db.Timestamptz

  /// Freeform notes on moderation appointment, limits, or context.
  moderator_notes String?

  /// Timestamp moderator record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp moderator record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for former moderator accounts.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_moderators_political_economic_7a1782c2")

  political_economic_board_moderation_queue political_economic_board_moderation_queue[]
  political_economic_board_moderator_actions political_economic_board_moderator_actions[]
  political_economic_board_event_logs political_economic_board_event_logs[]
  political_economic_board_metrics political_economic_board_metrics[]
  political_economic_board_data_anomalies political_economic_board_data_anomalies[]

  @@unique([political_economic_board_member_id], map: "political_economic_board_moderators_political_economic_809c874d")
  @@index([activated_at])
}

/// Highest privilege user accounts for site governance, role assignments,
/// escalations, and config changes. Linked to members (one-to-one, as only
/// members may be promoted). Full auditability and clear role separation are
/// essential. Distinguished from moderators by administrator status/level.
/// Action history recorded separately (see
/// political_economic_board_role_changes and logs).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged member's {@link political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// Timestamp administrator privileges were granted.
  activated_at DateTime @db.Timestamptz

  /// Timestamp administrator role revoked or expired, if applicable.
  deactivated_at DateTime? @db.Timestamptz

  /// Administrative comments or rationale for specific privileges, if any.
  admin_notes String?

  /// Timestamp administrator record created.
  created_at DateTime @db.Timestamptz

  /// Timestamp administrator record updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for administrator account (if downgraded or
  /// deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_administrators_political_econ_5a3ce1c9")

  political_economic_board_event_logs political_economic_board_event_logs[]
  political_economic_board_metrics political_economic_board_metrics[]
  political_economic_board_data_anomalies political_economic_board_data_anomalies[]

  @@unique([political_economic_board_member_id], map: "political_economic_board_administrators_political_econ_c1eb3803")
  @@index([activated_at])
}

/// Tracks all authenticated user sessions for members, moderators, and
/// administrators. Includes JWT/refresh tokens, device info, session expiry,
/// IP, and audit. Used for security, MFA, and suspicious activity detection.
/// Each row represents one authentication session; session ending triggers
/// record update to reflect closure.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_auth_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Session's owner member {@link political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// JWT/access token for current session (opaque storage, not user
  /// credentials).
  session_token String

  /// Refresh token for session lifecycle management.
  refresh_token String

  /// Details on device/browser used in the session.
  device_info String?

  /// IP address associated with this session.
  ip_address String?

  /// Expiration timestamp for session token.
  session_expires_at DateTime @db.Timestamptz

  /// Timestamp when session was terminated/revoked, if any.
  revoked_at DateTime? @db.Timestamptz

  /// Timestamp session created.
  created_at DateTime @db.Timestamptz

  /// Timestamp session last updated or extended.
  updated_at DateTime @db.Timestamptz

  /// Soft delete for session history retention, if expired/terminated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_auth_sessions_political_econo_8a89c22d")

  @@index([political_economic_board_member_id], map: "political_economic_board_auth_sessions_political_econo_e585683d")

  @@unique([session_token])
  @@unique([refresh_token])
  @@index([session_expires_at])
  @@index([created_at])
}

/// Email verification and secondary auth challenge table. Each token is
/// unique, time-bound, and belongs to a member. Supports registration
/// verification, password resets, and email challenge flows for MFA. Tokens
/// record purpose, target, and creation/expiry audit fields.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_verification_tokens {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Verification token's owner member {@link
  /// political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// Opaque random string representing the verification token value.
  token String

  /// Purpose of token: e.g., email_verification, reset_password, mfa.
  token_type String

  /// Additional context for this token, e.g., origin email, device, or request
  /// meta.
  context String?

  /// Timestamp after which token is invalid.
  expires_at DateTime @db.Timestamptz

  /// Timestamp when the token was used (if applicable).
  used_at DateTime? @db.Timestamptz

  /// Timestamp when token was generated.
  created_at DateTime @db.Timestamptz

  /// Timestamp last updated (e.g., reissued/rotated).
  updated_at DateTime @db.Timestamptz

  /// Soft delete if token invalidated or removed before expiry.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_verification_tokens_political_760d7f42")

  @@index([political_economic_board_member_id], map: "political_economic_board_verification_tokens_political_2fce5d83")

  @@unique([token])
  @@index([expires_at])
  @@index([created_at])
}

/// Manages all password reset flows and history. Stores reset tokens,
/// request/fulfillment audit data, and intent context. Token must be unique
/// per reset. Used by backend flows for secure user-initiated password
/// changes and automated lockout recovery. Security: sensitive context must
/// be purged after fulfillment or expiry.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner member who initiated password reset {@link
  /// political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// Random unique token for password reset authentication.
  reset_token String

  /// IP address from which reset was requested.
  request_ip String?

  /// Timestamp request was completed (password was changed).
  fulfilled_at DateTime? @db.Timestamptz

  /// Timestamp reset token becomes invalid.
  expires_at DateTime @db.Timestamptz

  /// Timestamp reset request created.
  created_at DateTime @db.Timestamptz

  /// Timestamp reset record last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp, if record removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_password_resets_political_eco_6e1cd7f2")

  @@index([political_economic_board_member_id], map: "political_economic_board_password_resets_political_eco_74f93e33")

  @@unique([reset_token])
  @@index([expires_at])
  @@index([created_at])
}

/// Audit table for all user role changes: log upgrades, demotions,
/// suspensions, reactivations, with rationale and actor chain. Each event
/// references a member, previous and new role, trigger origin
/// (admin/mod/system), and event context. This is the authoritative ledger
/// for permissions history and compliance tracing. Immutable except for soft
/// delete. Used for platform audits and compliance, but never modifies role
/// status; that is managed by role-specific tables.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_role_changes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target member for this role change log entry {@link
  /// political_economic_board_members.id}.
  political_economic_board_member_id String @db.Uuid

  /// Previous role before change (guest, member, moderator, administrator).
  old_role String

  /// New role after change (same value set as old_role).
  new_role String

  /// Freeform context for the change: reason, policy citation, compliance
  /// reference, etc.
  context String?

  /// Type of actor who initiated change (system, moderator, administrator).
  triggered_by_actor_type String

  /// Actor's ID (admin/mod/system id) responsible for change.
  triggered_by_actor_id String @db.Uuid

  /// Rationale or justification provided by triggering actor.
  change_reason String?

  /// Timestamp role change was logged.
  created_at DateTime @db.Timestamptz

  /// Timestamp role change record last updated (for audit sync).
  updated_at DateTime @db.Timestamptz

  /// Soft delete audit for compliance (never physical delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_role_changes_political_econom_ed06d7cc")

  @@index([political_economic_board_member_id], map: "political_economic_board_role_changes_political_econom_5da3a147")

  @@index([created_at])
}

schemas.schema-03-profiles.prisma:
/// Stores public profile data for each member, distinct from authentication
/// or role tables. Includes display name, bio, profile photo, join date, and
/// privacy settings. Each profile is linked to a single member entity in
/// political_economic_board_members, and may have multiple associated badges
/// and statistics. Designed for frequent updates and privacy-driven data
/// management.
///
/// @namespace Profiles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked member entity's {@link political_economic_board_members.id}.
  /// One-to-one relationship, ensures every profile belongs to one member.
  political_economic_board_member_id String @db.Uuid

  /// Public name visible to other users. 1-50 characters, must be unique
  /// across active profiles.
  display_name String

  /// Profile biography or summary, up to 500 characters. Optional.
  bio String?

  /// URL to uploaded profile photo (JPG/PNG, max 2MB). Optional.
  profile_photo_url String? @db.VarChar(80000)

  /// Date profile was first created or linked to a member. For analytics and
  /// display.
  join_date DateTime @db.Timestamptz

  /// Profile privacy setting (e.g., 'public', 'members_only', 'private').
  /// Business logic in API layer enforces allowed values.
  privacy_level String

  /// Timestamp when profile was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when profile was last updated (any non-deleted field).
  updated_at DateTime @db.Timestamptz

  /// Nullable timestamp for soft deletes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member political_economic_board_members @relation(fields: [political_economic_board_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_profiles_political_economic_b_5f8cb619")

  political_economic_board_profile_badges political_economic_board_profile_badges[]
  political_economic_board_profile_stats political_economic_board_profile_stats?
  political_economic_board_profile_changes political_economic_board_profile_changes[]

  @@unique([political_economic_board_member_id], map: "political_economic_board_profiles_political_economic_b_5b81d2f6")
  @@unique([display_name])
  @@index([privacy_level])
}

/// Tracks awarded badges or achievements to individual profiles,
/// representing user reputation, contributions, or recognition (e.g.,
/// 'founding member', 'top contributor'). Multiple badges can be assigned
/// per profile, each with type, issue date, optional expiration, and unique
/// badge code per profile. Enables flexible badge expansion and business
/// logic enforcement on award frequency and scope.
///
/// @namespace Profiles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_profile_badges {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target profile's {@link political_economic_board_profiles.id} receiving
  /// this badge.
  political_economic_board_profile_id String @db.Uuid

  /// Unique code or slug representing badge type. E.g., 'founding_member',
  /// 'top_contributor'.
  badge_code String

  /// Display title for badge ('Founding Member', etc.).
  title String

  /// Longer description of the badge's meaning or achievement. Optional.
  description String?

  /// Timestamp when badge was granted to the profile.
  issued_at DateTime @db.Timestamptz

  /// Nullable timestamp for expiration for time-limited awards.
  expires_at DateTime? @db.Timestamptz

  /// Timestamp row was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last badge update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile political_economic_board_profiles @relation(fields: [political_economic_board_profile_id], references: [id], onDelete: Cascade, map: "political_economic_board_profile_badges_political_econ_df327471")

  @@unique([political_economic_board_profile_id, badge_code], map: "political_economic_board_profile_badges_political_econ_6d50fb24")
  @@index([badge_code])
  @@index([issued_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Maintains aggregate, de-identified activity metrics for each profile
/// (posts, comments, votes, reactions, earned badges, and reputation score).
/// Allows fast retrieval of user stats and supports periodic recalculation
/// by business logic. Data is aggregate, not individual events, and can be
/// reset or recalculated. Profile stats are used in profile displays,
/// leaderboards, and eligibility checks for advanced features or moderation.
///
/// @namespace Profiles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_profile_stats {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Profile being summarized. Foreign key to {@link
  /// political_economic_board_profiles.id}.
  political_economic_board_profile_id String @db.Uuid

  /// Total number of non-deleted posts authored by this profile.
  posts_count Int @db.Integer

  /// Total number of comments authored by this profile.
  comments_count Int @db.Integer

  /// Total number of upvotes/downvotes cast by this user.
  votes_cast_count Int @db.Integer

