/// Records all significant actions, events, and system occurrences for the
/// platform including user activity, moderation steps, system events, and
/// error states. Serves as a source of truth for audit, health monitoring,
/// and analytics. Supports filtering by type, subject, actor, or system
/// area. Events can originate from users, automated systems, or
/// integrations. Supports flexible payload for forward-compatibility. Strong
/// indexation for time-based and type-based queries. Full-text search
/// enabled for event_message.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_event_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Acting user's {@link political_economic_board_members.id} in triggered
  /// event, if applicable.
  actor_member_id String? @db.Uuid

  /// Acting moderator's {@link political_economic_board_moderators.id} when
  /// event relates to moderation, if applicable.
  actor_moderator_id String? @db.Uuid

  /// Acting administrator's {@link political_economic_board_administrators.id}
  /// when event originates from an admin.
  actor_admin_id String? @db.Uuid

  /// Type/category of event (e.g., post_created, comment_deleted,
  /// login_attempt, moderation_action, system_error). Enables filtering and
  /// aggregation.
  event_type String

  /// Entity type the event refers to (e.g., post, comment, profile, api,
  /// system); supports analytics on activity by object kind.
  target_object_type String

  /// String identifier for the object targeted by this event (UUID, DB id, or
  /// external ref); used for tracing affected domain record.
  target_object_id String?

  /// Detailed message for logging/search. May include metadata, descriptive
  /// context, or error traces. Used in dashboards/alerts.
  event_message String?

  /// JSON-formatted raw event payload enabling arbitrary, extensible logging
  /// of additional data; used for version-tolerant analytics.
  payload_json String?

  /// What triggered/logged the event (user, system, automated job, integration
  /// name); used for analytics and security audit.
  source String?

  /// Timestamp when the event was logged. Indexed for timeline/retention
  /// queries.
  created_at DateTime @db.Timestamptz

  /// Last update time of the event record (rarely modified except for error
  /// correction or audit trail).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion marker; null if record is active. Used for retention and
  /// legal hold.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  actorMember    political_economic_board_members?        @relation(fields: [actor_member_id], references: [id], onDelete: Cascade)
  actorModerator political_economic_board_moderators?     @relation(fields: [actor_moderator_id], references: [id], onDelete: Cascade)
  actorAdmin     political_economic_board_administrators? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)

  @@index([event_type])
  @@index([created_at])
  @@index([actor_member_id])
  @@index([actor_moderator_id])
  @@index([actor_admin_id])
  @@index([event_message(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Stores aggregated or point-in-time analytics metrics (e.g., MAU, DAU,
/// post_counts, report_counts, median_moderation_time) supporting platform
/// health dashboards, KPI tracking, and business analysis. Each metric is
/// associated with a name, value, window, and time granularity. Key for
/// longitudinal studies, performance reporting, and business success
/// evaluation. Metrics should be filtered and aggregated by name, window,
/// and time. Referential integrity with period-specific owners is possible
/// via nullable foreign keys.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_metrics {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Metric calculated for a specific member's {@link
  /// political_economic_board_members.id} actions, if applicable (e.g., user
  /// retention, activity rates).
  owner_member_id String? @db.Uuid

  /// Metric calculated for a specific moderator's {@link
  /// political_economic_board_moderators.id} performance or behavior.
  owner_moderator_id String? @db.Uuid

  /// Metric tied to an admin's {@link
  /// political_economic_board_administrators.id} period (for admin-related
  /// analytics).
  owner_admin_id String? @db.Uuid

  /// Business label for the metric (e.g., 'dau', 'mau', 'median_mod_time',
  /// 'posts_today', 'post_quality_score'). Used in dashboards and analytics.
  metric_name String

  /// Value of the metric; semantic depends on name but always represents a
  /// quantitative measurement available for statistics/KPI reporting.
  metric_value Float @db.DoublePrecision

  /// Time window start for the metric value (e.g., midnight for daily, first
  /// of month for monthly metrics). For point-in-time metrics use created_at.
  window_start DateTime @db.Timestamptz

  /// Time window end for the metric value; same as window_start for
  /// snapshot/instantaneous metrics.
  window_end DateTime @db.Timestamptz

  /// Resolution of the metric (daily, weekly, monthly, real_time, etc.); used
  /// for aggregation/rollup in dashboards. Strongly affects analytics queries.
  granularity String

  /// Optional detailed description, policy, calculation method, or comments
  /// about metric context. Documentation/audit support.
  notes String?

  /// When the metric record was first written (for versioned or rolling
  /// metrics, this is recalculated or retracked for new windows).
  created_at DateTime @db.Timestamptz

  /// Last modification time for the metric (e.g., re-computed for correction
  /// or business rule update).
  updated_at DateTime @db.Timestamptz

  /// Soft delete marker for expired/obsolete metrics (retained for audit and
  /// rollback).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ownerMember    political_economic_board_members?        @relation(fields: [owner_member_id], references: [id], onDelete: Cascade)
  ownerModerator political_economic_board_moderators?     @relation(fields: [owner_moderator_id], references: [id], onDelete: Cascade)
  ownerAdmin     political_economic_board_administrators? @relation(fields: [owner_admin_id], references: [id], onDelete: Cascade)

  @@unique([metric_name, window_start, window_end, granularity], map: "political_economic_board_metrics_metric_name_window_st_0f2f9990")
  @@index([owner_member_id])
  @@index([owner_moderator_id])
  @@index([owner_admin_id])
  @@index([created_at])
}

/// Tracks analytics, engagement, or system anomalies that may signal data
/// quality issues, security events, business process exceptions, or
/// unexpected user/system behavior. Used for business incident triage,
/// process improvement, and compliance monitoring. Supports triage,
/// investigation, assignment, and resolution tracking for all anomaly
/// entries. Supports full-text search for anomaly type, description, and
/// context information.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_data_anomalies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User (member) {@link political_economic_board_members.id} who reported or
  /// detected the anomaly, if applicable.
  detected_by_member_id String? @db.Uuid

  /// Moderator {@link political_economic_board_moderators.id} who reported the
  /// anomaly.
  detected_by_moderator_id String? @db.Uuid

  /// Admin {@link political_economic_board_administrators.id} who flagged or
  /// confirmed the anomaly.
  detected_by_admin_id String? @db.Uuid

  /// Category of anomaly (e.g., data_inconsistency, metrics_spike,
  /// missing_event, moderation_delay, duplicate_action, kpi_drop,
  /// suspicious_activity, integration_failure). Supports reporting and
  /// filtering.
  anomaly_type String

  /// Current resolution state (open, in_progress, resolved, false_positive,
  /// ignored); business process triage status for workflow.
  anomaly_status String

  /// Human-readable description of anomaly context, impact, and known data.
  /// Supports dashboarding, audit, search, and recall.
  anomaly_description String

  /// Documentation of investigation steps, findings, explanation, resolution
  /// actions. Fully auditable for compliance.
  resolution_notes String?

  /// Time the anomaly was detected (for automated/real-time, usually the
  /// incident trigger time).
  detected_at DateTime @db.Timestamptz

  /// Time anomaly was resolved or marked no-action (can be null if
  /// unresolved/ongoing).
  resolved_at DateTime? @db.Timestamptz

  /// When the anomaly entry was persisted for audit trail and process tracking.
  created_at DateTime @db.Timestamptz

  /// Last time this anomaly or its status/notes changed; used for monitoring
  /// and compliance.
  updated_at DateTime @db.Timestamptz

  /// If non-null, the anomaly is soft-deleted or under legal hold. Used for
  /// retention review.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  detectedByMember    political_economic_board_members?        @relation(fields: [detected_by_member_id], references: [id], onDelete: Cascade, map: "political_economic_board_data_anomalies_detected_by_me_30da0e15")
  detectedByModerator political_economic_board_moderators?     @relation(fields: [detected_by_moderator_id], references: [id], onDelete: Cascade, map: "political_economic_board_data_anomalies_detected_by_mo_15cde9fb")
  detectedByAdmin     political_economic_board_administrators? @relation(fields: [detected_by_admin_id], references: [id], onDelete: Cascade, map: "political_economic_board_data_anomalies_detected_by_ad_af37b186")

  @@index([detected_by_member_id], map: "political_economic_board_data_anomalies_detected_by_me_d1dd6e6f")
  @@index([detected_by_moderator_id], map: "political_economic_board_data_anomalies_detected_by_mo_d808ebd5")
  @@index([detected_by_admin_id], map: "political_economic_board_data_anomalies_detected_by_ad_863eaeec")
  @@index([anomaly_type])
  @@index([anomaly_status])
  @@index([detected_at])
  @@index([anomaly_description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-10-integrations.prisma:
/// Stores detailed logs of all interactions and payloads exchanged with
/// third-party content moderation providers for auditing, monitoring, and
/// compliance within the politicalEconomicBoard platform. Records provider,
/// request/response payloads, statuses, errors, and reference to the
/// high-level moderation action or report if available. This table enables
/// precise troubleshooting, quality assurance, and dispute handling for
/// moderation events, with typical queries by moderation action, provider,
/// or status.
///
/// @namespace Integrations
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_moderation_provider_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the triggering report's {@link
  /// political_economic_board_reports.id}.
  political_economic_board_reports_id String? @db.Uuid

  /// Name or identifier of the third-party moderation provider servicing this
  /// API call (e.g., 'OpenAI', 'AWS Comprehend').
  provider String

  /// Full raw payload sent to the provider, stored as JSON string for audit
  /// tracing.
  request_payload String

  /// Full raw response received from the provider, stored as JSON string for
  /// compliance and debugging.
  response_payload String

  /// Status of the provider interaction (e.g., 'success', 'error', 'timeout').
  status String

  /// Full error message or exception information if the provider call failed.
  /// Null if no error occurred.
  error_message String?

  /// External reference/correlation ID returned by the provider for
  /// tracing/debugging. Null if unavailable.
  external_reference_id String?

  /// Timestamp this log entry was created (provider call initiation).
  created_at DateTime @db.Timestamptz

  /// Last time this log was updated (e.g., status or error detail added).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  report political_economic_board_reports? @relation(fields: [political_economic_board_reports_id], references: [id], onDelete: Cascade, map: "political_economic_board_moderation_provider_logs_poli_1a7e2c11")

  @@unique([provider, external_reference_id], map: "political_economic_board_moderation_provider_logs_prov_fb0d1433")
  @@index([provider, status], map: "political_economic_board_moderation_provider_logs_prov_e000ab56")
  @@index([created_at], map: "political_economic_board_moderation_provider_logs_crea_fc9da9cb")
  @@index([political_economic_board_reports_id], map: "political_economic_board_moderation_provider_logs_poli_a6517d8d")
  @@index([error_message(ops: raw("gin_trgm_ops"))], type: Gin, map: "political_economic_board_moderation_provider_logs_erro_2192ae82")
}

/// Comprehensive log table for all notification interactions with
/// third-party messaging providers (email, SMS, push) from the
/// politicalEconomicBoard. Tracks outgoing notification attempts, provider
/// responses, delivery status, errors, and allows tracing via notification
/// reference. Supports transparent audit, troubleshooting notification
/// issues, and monitoring provider reliability. Indexed for provider,
/// status, and timestamp for performance.
///
/// @namespace Integrations
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_notification_provider_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the dispatched notification's {@link
  /// political_economic_board_notifications.id}.
  political_economic_board_notifications_id String? @db.Uuid

  /// Name or identifier of the messaging provider used for notification (e.g.,
  /// 'SendGrid', 'Twilio', 'APNs').
  provider String

  /// Full JSON payload sent to provider (e.g., message body, to/address), for
  /// audit/debug.
  request_payload String

  /// Full JSON response from provider (including any metadata, delivery
  /// receipts).
  response_payload String

  /// Provider transaction status (e.g., 'sent', 'delivered', 'failed',
  /// 'queued').
  status String

  /// Error message/content, if any, for failed attempts. Null if successful.
  error_message String?

  /// Provider-assigned message or correlation ID for cross-referencing. Null
  /// if unavailable.
  external_reference_id String?

  /// Timestamp of when this log record was created (notification send attempt).
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update (e.g., final delivery status).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  notification political_economic_board_notifications? @relation(fields: [political_economic_board_notifications_id], references: [id], onDelete: Cascade, map: "political_economic_board_notification_provider_logs_po_fbe8a248")

  @@unique([provider, external_reference_id], map: "political_economic_board_notification_provider_logs_pr_cb764d98")
  @@index([provider, status], map: "political_economic_board_notification_provider_logs_pr_243a623d")
  @@index([created_at], map: "political_economic_board_notification_provider_logs_cr_604fae83")
  @@index([political_economic_board_notifications_id], map: "political_economic_board_notification_provider_logs_po_589815e4")
  @@index([error_message(ops: raw("gin_trgm_ops"))], type: Gin, map: "political_economic_board_notification_provider_logs_er_f0b3efde")
}

/// Centralized log for all third-party API calls (analytics, SSO, research
/// APIs, integrations) initiated from the politicalEconomicBoard platform,
/// for compliance, investigation, and support. Stores API provider details,
/// endpoint, request/response payloads, status, error detail, and external
/// transaction/correlation identifiers where available. Timely and
/// well-indexed for troubleshooting and governance. Generic enough to
/// accommodate new API integrations without schema change.
///
/// @namespace Integrations
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model political_economic_board_external_api_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Vendor or API provider name (e.g., 'Google Analytics', 'Okta SSO',
  /// 'ModerationAI').
  provider String

  /// Identifies the API method, endpoint, or path invoked (e.g., '/analyze',
  /// '/login').
  api_endpoint String

  /// JSON string of the request sent to the API (for later investigation or
  /// support).
  request_payload String

  /// JSON string of the response received from the API (complete trace for
  /// auditing).
  response_payload String

  /// API call status (e.g., 'success', 'failed', 'delayed').
  status String

  /// Error message, if any, received from the external API. Null if
  /// successful/no error.
  error_message String?

  /// Third-party correlation or transaction code for this API call. Null if
  /// unavailable.
  external_reference_id String?

  /// Timestamp of log record creation (call attempt).
  created_at DateTime @db.Timestamptz

  /// Last update to the log record (e.g., after a delayed status or error
  /// reported).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([provider, external_reference_id], map: "political_economic_board_external_api_logs_provider_ex_d7c28cf1")
  @@index([provider, status])
  @@index([created_at])
  @@index([error_message(ops: raw("gin_trgm_ops"))], type: Gin)
}

